const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),png=require('./png.cjs');const{createCanvas,loadImage}=require('C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/@napi-rs/canvas');
(async()=>{let url='http://127.0.0.1:8765/api/project?id=test-town-body02-idle-walk-20261031',r=await fetch(url);assert(r.ok);let raw=await r.text(),p=JSON.parse(raw),c=structuredClone(p),etag=r.headers.get('etag'),out=path.resolve('备份/20261031-测试人物改为32x64-'+Date.now());fs.mkdirSync(out,{recursive:true});fs.writeFileSync(out+'/before.json',raw);fs.writeFileSync(out+'/metadata.json',JSON.stringify({etag,sha256:crypto.createHash('sha256').update(raw).digest('hex')}));
async function twice(url){let im=await loadImage(url),cv=createCanvas(im.width*2,im.height*2),ctx=cv.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(im,0,0,cv.width,cv.height);let a=png.decode(Buffer.from(url.split(',')[1],'base64')),b=ctx.getImageData(0,0,cv.width,cv.height);for(let y=0;y<b.height;y++)for(let x=0;x<b.width;x++){let i=(Math.floor(y/2)*a.width+Math.floor(x/2))*4,j=(y*b.width+x)*4;assert.deepEqual([...b.data.slice(j,j+4)],[...a.data.slice(i,i+4)])}return cv.toDataURL()}
for(let s of c.spriteSheets){assert.equal(s.frameWidth,16);assert.equal(s.frameHeight,32);s.frameWidth=32;s.frameHeight=64;for(let a of s.actions)for(let f of a.frames){f.width*=2;f.height*=2;f.sourceX*=2;f.sourceY*=2;f.lockedRegions?.forEach(rect=>{for(let k of ['x','y','width','height','w','h'])if(typeof rect[k]==='number')rect[k]*=2;});}if(s.imageDataURL)s.imageDataURL=await twice(s.imageDataURL);}
let count=0;for(let l of c.layers)for(let f of Object.values(l.frameData||{})){f.dataURL=await twice(f.dataURL);f.width*=2;f.height*=2;if(f.placement)for(let k of ['x','y','w','h'])f.placement[k]*=2;count++;}assert.equal(c.layers.length,p.layers.length);for(let i=0;i<p.layers.length;i++){let a={...p.layers[i]},b={...c.layers[i]};delete a.frameData;delete b.frameData;assert.deepEqual(a,b)}let cv=createCanvas(256,256),ctx=cv.getContext('2d');ctx.fillStyle='#d9d1e1';ctx.fillRect(0,0,256,256);ctx.imageSmoothingEnabled=false;for(let l of c.layers){if(l.sheetIndex!==0||!l.visible)continue;let f=l.frameData['0_3_0'];if(!f)continue;let im=await loadImage(f.dataURL);ctx.drawImage(im,64,0,128,256)}fs.writeFileSync(out+'/正面32x64预览.png',cv.toBuffer('image/png'));fs.writeFileSync(out+'/candidate.json',JSON.stringify(c));let check=await fetch(url);assert.equal(check.headers.get('etag'),etag,'Concurrent save');let put=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':etag},body:JSON.stringify(c)}),reply=await put.text();assert.equal(put.status,200,reply);let readback=await(await fetch(url)).text();assert.deepEqual(JSON.parse(readback),c);fs.writeFileSync(out+'/api-readback.json',readback);fs.writeFileSync(out+'/verification.json',JSON.stringify({count,scale:2,cell:[32,64],nearestNeighborExact:true,layerMetadataPreserved:true,status:put.status,readbackExact:true},null,2));console.log(out+'\nSAVED '+count+' cels; exact 2x pixels verified');})();
